window.DosulEffectIcons={
  entry(name){const value=window.DOSUL_EFFECT_ICONS?.icons?.[name];if(!value)return null;return typeof value==='string'?{src:value,kind:'etc',sourceName:name}:value;},
  src(name){return this.entry(name)?.src||'';},
  kind(name,fallback='etc'){return this.entry(name)?.kind||fallback;},
  sourceName(name){return this.entry(name)?.sourceName||name;},
  names(){return Object.keys(window.DOSUL_EFFECT_ICONS?.icons||{});}
};
